package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.Build;import android.view.*;import android.widget.*;
/** Bounded bottom sheet: fields scroll independently of the reachable action footer. */
final class SheetDialog extends GlassDialog {
 final LinearLayout footer;final BoundedColumn layout;final ScrollView scroll;
 SheetDialog(Activity a,View content){super(a,Glass.dark(a)?R.style.GlassSheetDark:R.style.GlassSheet);Glass.privacy(getWindow(),a);requestWindowFeature(Window.FEATURE_NO_TITLE);layout=new BoundedColumn(a);layout.setOrientation(1);layout.setPadding(0,Glass.dp(a,10),0,Glass.dp(a,4));View handle=new View(a);handle.setBackground(Glass.round(a,Glass.alpha(Glass.subtle(a),100),4));LinearLayout.LayoutParams h=new LinearLayout.LayoutParams(Glass.dp(a,36),Glass.dp(a,4));h.gravity=Gravity.CENTER_HORIZONTAL;h.bottomMargin=Glass.dp(a,2);layout.addView(handle,h);scroll=new ScrollView(a);scroll.setFillViewport(false);scroll.setVerticalScrollBarEnabled(false);scroll.setClipToPadding(false);scroll.addView(content);layout.addView(scroll,new LinearLayout.LayoutParams(-1,-2,1));footer=Modern.column(a);footer.setPadding(Glass.dp(a,18),0,Glass.dp(a,18),Glass.dp(a,12));layout.addView(footer,new LinearLayout.LayoutParams(-1,-2));setContentView(layout);layout.getViewTreeObserver().addOnGlobalLayoutListener(()->{Rect r=new Rect();layout.getWindowVisibleDisplayFrame(r);int width=Math.min(Glass.dp(a,480),a.getResources().getDisplayMetrics().widthPixels-Glass.dp(a,16));if(getWindow()!=null&&getWindow().getAttributes().width!=width)getWindow().setLayout(width,-2);int height=r.height();if(height>Glass.dp(a,120)&&Math.abs(layout.visibleHeight-height)>Glass.dp(a,4)){layout.visibleHeight=height;layout.requestLayout();}});}
 void actions(String title,Runnable save){LinearLayout row=Modern.row(getContext());Button cancel=Glass.button(getContext(),"Cancelar"),commit=Glass.button(getContext(),title);LinearLayout.LayoutParams c=new LinearLayout.LayoutParams(0,-2,.36f);c.rightMargin=Glass.dp(getContext(),8);row.addView(cancel,c);row.addView(commit,new LinearLayout.LayoutParams(0,-2,.64f));footer.addView(row);cancel.setOnClickListener(v->dismiss());commit.setOnClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.CONFIRM);save.run();});}
 static final class BoundedColumn extends LinearLayout {int visibleHeight;BoundedColumn(Context c){super(c);}protected void onMeasure(int width,int height){int maximum=(visibleHeight>0?visibleHeight:getResources().getDisplayMetrics().heightPixels)-Glass.dp(getContext(),46);if(visibleHeight<=0&&Build.VERSION.SDK_INT>=30&&getRootWindowInsets()!=null){android.graphics.Insets bars=getRootWindowInsets().getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());maximum-=bars.top+bars.bottom;}maximum=Math.max(Glass.dp(getContext(),160),maximum);super.onMeasure(width,MeasureSpec.makeMeasureSpec(Math.min(maximum,MeasureSpec.getMode(height)==MeasureSpec.UNSPECIFIED?maximum:MeasureSpec.getSize(height)),MeasureSpec.AT_MOST));}}
}
